    msg(node, `به ${fa(out.recipients)} نفر رفت — ${fa(out.sent)} موفق، ${fa(out.error)} ناموفق. گزارشش در «مرکز اعلان» است.`, 'ok');
  } catch (err) { msg(node, err.message, 'bad'); }
