    contact.dir = 'ltr';
    tr.appendChild(contact);

    tr.appendChild(el('td', null, u.station_name
      ? `${u.station_name} (${u.station_code})` : '—'));
    tr.appendChild(el('td', null, PUMP_ROLE_FA[u.role] || u.role || '—'));

