    tr.appendChild(el('td', null, t.app === 'pump' ? 'پمپ' : 'دکان'));
    tr.appendChild(el('td', null, (t.lastMessage || '').slice(0, 60) || '—'));
    tr.appendChild(el('td', null, t.unreadAdmin ? fa(t.unreadAdmin) : '—'));
