/** صدور یا تمدید اشتراک یک دکان. */
router.post('/subscriptions', async (req, res, next) => {
  const shopId = v.id(req.body?.shopId, { field: 'شناسه دکان' });
  const plan = v.text(req.body?.plan, { max: 20 }) || 'custom';
  const days = req.body?.days === undefined || req.body?.days === null || req.body?.days === ''
    ? null : v.integer(req.body.days, { field: 'روزها', min: 1, max: 3650 });
  const features = sanitizeFeatures(req.body?.features);
  const maxDevices = v.integer(req.body?.maxDevices, { field: 'تعداد دستگاه', min: 1, max: 100, def: 10 });
  const graceDays = v.integer(req.body?.graceDays, { field: 'مهلت', min: 0, max: 90, def: 0 });
  const note = v.text(req.body?.note, { max: 300 });

  /*
   *  ⛔ F0-14 — کلیدِ یکتایی. پنل برای هر ثبت یک `Idempotency-Key`
   *  می‌فرستد؛ تکرارِ همان ثبت (دو بار کلیک، قطعِ شبکه) پاسخِ اول را
   *  پس می‌گیرد و دورهٔ دوم نمی‌سازد. بی‌کلید ⇒ رفتارِ قبلی (سازگاری).
   *  ‎lib/idempotency.js‎
   */
  const idem = idempotency.fromRequest(req, `sub-grant:shop:${req.admin.id}`);
  const replay = (response) => {
    const sub = response.subscription;
    res.set('Idempotent-Replayed', 'true');
    return res.status(201).json({ subscription: sub, state: subs.stateOf(sub), discount: response.discount ?? null });
  };
  if (idem) {
    const prior = await idempotency.find(idem);
    if (prior) return replay(prior.response);
  }

  /*
   *  قیمت و کدِ تخفیف — اختیاری. کدِ تخفیف اول سنجیده می‌شود (مهلت،
   *  سقف، یک‌بار برای هر مشتری) و قیمتِ نهایی‌اش روی خودِ اشتراک
   *  می‌نشیند؛ بعد از صدور، خرجِ کد ثبت می‌شود.
   */
  const discounts = require('../lib/discounts');
  let price = req.body?.price === undefined || req.body?.price === null || req.body?.price === ''
    ? null : v.integer(req.body.price, { field: 'قیمت', min: 0, max: 1e9 });
  let quoted = null;
  if (req.body?.discountCode) {
    const shop = await one('SELECT owner_user_id FROM shops WHERE id=$1', [shopId]);
    try {
      quoted = await discounts.quote(req.body.discountCode, { app: 'shop', plan, userId: shop ? shop.owner_user_id : '' });
    } catch (err) {
      //  تکرارِ هم‌زمان: درخواستِ اول کد را خرج کرده و کلید را ثبت کرده است
      const prior = idem ? await idempotency.find(idem) : null;
      if (prior) return replay(prior.response);
      throw err;
    }
    if (quoted.finalPrice !== null) price = quoted.finalPrice;
  }

  const granted = await subs.grantOnce(shopId, {
    plan, days, features, maxDevices, graceDays, note, createdBy: req.admin.id, price,
    startsAt: v.timestamp(req.body?.startsAt), endsAt: v.timestamp(req.body?.endsAt),
    allowUnsuspend: true,
  }, idem, { discount: quoted });
  if (granted.replayed) return replay(granted.response);
  const sub = granted.row;
  if (quoted) {
    await discounts.useCode(quoted.code.id, {
      app: 'shop', userId: (await one('SELECT owner_user_id FROM shops WHERE id=$1', [shopId]))?.owner_user_id || '',
      tenantId: shopId, subscriptionId: sub.id, price: quoted.price || 0, finalPrice: quoted.finalPrice || 0,
    });
  }
  const reason = reasonOf(req);   // اختیاری — فقط در سابقه (ADMIN-CONTROL-PLANE.md G2)
  await audit.log({ shopId, actorType: 'admin', userId: req.admin.id, action: 'admin.subscription_granted', targetType: 'subscription', targetId: sub.id, detail: { plan, days, price, ...(reason ? { reason } : {}) } });
  res.status(201).json({ subscription: sub, state: subs.stateOf(sub), discount: quoted });
});

/** ویرایش اشتراک (تاریخ پایان، قابلیت‌ها، یادداشت). */
router.put('/subscriptions/:id', async (req, res, next) => {
  const id = v.id(req.params.id);
  const current = await one('SELECT * FROM subscriptions WHERE id=$1', [id]);
  if (!current) return next(notFound('اشتراک پیدا نشد'));

  const endsAt = v.timestamp(req.body?.endsAt, { def: Number(current.ends_at) });
  const startsAt = v.timestamp(req.body?.startsAt, { def: Number(current.starts_at) });
  if (endsAt <= startsAt) return next(badRequest('تاریخ پایان باید بعد از شروع باشد'));
  const features = req.body?.features ? sanitizeFeatures(req.body.features) : current.features;
  const plan = v.text(req.body?.plan, { max: 20 }) || current.plan;
  const note = req.body?.note === undefined ? current.note : v.text(req.body.note, { max: 300 });
  const graceDays = v.integer(req.body?.graceDays, { min: 0, max: 90, def: current.grace_days });
  const maxDevices = v.integer(req.body?.maxDevices, { min: 1, max: 100, def: current.max_devices });

  const row = await one(
    `UPDATE subscriptions SET plan=$2, starts_at=$3, ends_at=$4, features=$5::jsonb,
            grace_days=$6, max_devices=$7, note=$8, updated_at=$9 WHERE id=$1 RETURNING *`,
    [id, plan, startsAt, endsAt, JSON.stringify(features), graceDays, maxDevices, note, now()]
  );
  const reason = reasonOf(req);   // اختیاری — فقط در سابقه (ADMIN-CONTROL-PLANE.md G2)
  await audit.log({ shopId: row.shop_id, actorType: 'admin', userId: req.admin.id, action: 'admin.subscription_updated', targetType: 'subscription', targetId: id, detail: reason ? { reason } : {} });
  res.json({ subscription: row, state: subs.stateOf(row) });
});

