router.patch('/plans/:code', requireSuperAdmin, async (req, res, next) => {
  const code = v.text(req.params.code, { max: 20, required: true, field: 'کد پلن' });
  const app = appOf(req);
  const p = await plans.getPlan(code, app);
  if (!p) return next(notFound('پلن پیدا نشد'));
  /*
   *  ⚠️ `AND app=$13` — و این تازه اضافه شده.
   *
   *  تا دیروز شرط فقط `WHERE code=$1` بود، یعنی عوض کردنِ قیمتِ «m1»ی
   *  دکان، قیمتِ «m1»ی پمپ را هم عوض می‌کرد. دو بخش یک جدول داشتند و
   *  همین یک خط، قیمتشان را به هم گره زده بود — بدترین جای ممکن برای
   *  قاطی شدن، چون مستقیم روی پول است.
   */
  const row = await one(
    `UPDATE plans SET title=$2, amount=$3, unit=$4, price_afn=$5, negotiable=$6,
            badge=$7, sort_order=$8, active=$9, max_devices=$10, features=$11::jsonb, updated_at=$12
      WHERE code=$1 AND app=$13 RETURNING *`,
    [code,
      v.text(req.body?.title, { max: 60 }) || p.title,
      req.body?.amount === undefined ? p.amount : v.integer(req.body.amount, { min: 1, max: 120 }),
      req.body?.unit === undefined ? p.unit : v.oneOf(req.body.unit, ['day', 'week', 'month', 'year'], { field: 'واحد' }),
      req.body?.price === undefined ? p.price_afn : v.integer(req.body.price, { min: 0, max: 1e7 }),
      v.bool(req.body?.negotiable, p.negotiable),
      req.body?.badge === undefined ? p.badge : v.text(req.body.badge, { max: 30 }),
      req.body?.sortOrder === undefined ? p.sort_order : v.integer(req.body.sortOrder, { min: 0, max: 999 }),
      v.bool(req.body?.active, p.active),
      req.body?.maxDevices === undefined ? p.max_devices : v.integer(req.body.maxDevices, { min: 1, max: 100 }),
      JSON.stringify(req.body?.features ? sanitizeFeatures(req.body.features, app) : p.features),
      now(), app]
  );
  //  تاریخچهٔ قیمت — هر بار که عدد واقعاً عوض شد یک ردیف. اشتراک‌های
  //  قبلی قیمتِ خودشان را دارند و از این تغییر اثر نمی‌گیرند.
  if (row && Number(row.price_afn) !== Number(p.price_afn)) {
    await require('../lib/discounts').recordPrice({
      app, plan: code, prevPrice: Number(p.price_afn), price: Number(row.price_afn), changedBy: req.admin.id,
    });
  }
  await audit.log({ actorType: 'admin', userId: req.admin.id, action: 'admin.plan_updated', targetType: 'plan', targetId: `${app}:${code}`, detail: { prevPrice: Number(p.price_afn), price: Number(row?.price_afn) } });
  res.json({ plan: row });
});

router.patch('/config', requireSuperAdmin, async (req, res) => {
  /*
   *  ⚠️ بخشِ پمپ کلیدهای خودش را دارد و باید داشته باشد: قیمتِ پلن‌های
   *  پمپ دالری است و دورهٔ آزمایشی‌اش هم جدا (`entitlement.js` از
   *  `pump_trial_days` می‌خواند). بی این دو، پنل نمی‌توانست عوضشان کند
   *  و «۱۲۰» با واحدِ افغانیِ دکان نشان داده می‌شد.
   */
  const allowed = [
    'trial_days', 'whatsapp_number', 'whatsapp_message', 'currency',
    'pump_trial_days', 'pump_currency',
  ];
  for (const key of allowed) {
    if (req.body?.[key] !== undefined) await plans.setConfig(key, v.text(req.body[key], { max: 300 }));
  }
  await audit.log({ actorType: 'admin', userId: req.admin.id, action: 'admin.config_updated' });
  res.json({ config: await plans.publicConfig() });
});

// ---------- درخواست‌های خرید ----------
router.get('/purchase-requests', async (req, res) => {
  const status = v.text(req.query?.status, { max: 20 }) || 'pending';
  const rows = await many(
    `SELECT p.*, s.name AS shop_name, u.name AS user_name, u.phone
       FROM purchase_requests p
       JOIN shops s ON s.id=p.shop_id
       JOIN users u ON u.id=p.user_id
      WHERE p.status=$1 ORDER BY p.created_at DESC LIMIT 200`,
    [status]
  );
  res.json({ requests: rows });
});

router.post('/purchase-requests/:id/approve', async (req, res, next) => {
  const id = v.id(req.params.id);
  const reqRow = await one(`SELECT * FROM purchase_requests WHERE id=$1 AND status='pending'`, [id]);
  if (!reqRow) return next(notFound('درخواست پیدا نشد'));
  const days = req.body?.days ? v.integer(req.body.days, { min: 1, max: 3650 }) : null;
  const sub = await subs.grant(reqRow.shop_id, {
    plan: reqRow.plan_code, days, createdBy: req.admin.id, note: reqRow.note, allowUnsuspend: true,
  });
  await query(`UPDATE purchase_requests SET status='approved', handled_at=$2, handled_by=$3 WHERE id=$1`,
    [id, now(), req.admin.id]);
  const reason = reasonOf(req);   // اختیاری — فقط در سابقه (ADMIN-CONTROL-PLANE.md G2)
  await audit.log({ shopId: reqRow.shop_id, actorType: 'admin', userId: req.admin.id, action: 'admin.request_approved', targetId: id, detail: reason ? { reason } : {} });
  res.json({ subscription: sub, state: subs.stateOf(sub) });
});

router.post('/purchase-requests/:id/reject', async (req, res) => {
  const id = v.id(req.params.id);
  const done = await one(
    `UPDATE purchase_requests SET status='rejected', handled_at=$2, handled_by=$3 WHERE id=$1 AND status='pending' RETURNING shop_id`,
    [id, now(), req.admin.id]);
  //  ردیفِ سابقه فقط وقتی واقعاً رد شد — دوباره‌زدن ردیفِ دوم نمی‌سازد.
  //  دلیل (اگر آمد — برنامهٔ مدیرِ اندروید می‌فرستد) همان‌جا می‌ماند.
  if (done) {
    await audit.log({
      shopId: done.shop_id, actorType: 'admin', userId: req.admin.id, action: 'admin.request_rejected',
      targetType: 'purchase_request', targetId: id, detail: { reason: reasonOf(req) },
    });
  }
  res.json({ ok: true });
});

// ---------- سابقه ----------
router.get('/audit', async (req, res) => {
  const limit = v.integer(req.query?.limit, { min: 1, max: 500, def: 100 });
  const shopId = v.id(req.query?.shopId, { required: false });
  const rows = shopId
    ? await many('SELECT * FROM audit_logs WHERE shop_id=$1 ORDER BY created_at DESC LIMIT $2', [shopId, limit])
    : await many('SELECT * FROM audit_logs ORDER BY created_at DESC LIMIT $1', [limit]);
  res.json({ entries: rows });
});

// ---------- مدیران ----------
router.post('/admins', requireSuperAdmin, async (req, res, next) => {
  const username = v.text(req.body?.username, { max: 40, required: true, field: 'نام کاربری' }).toLowerCase();
  const password = typeof req.body?.password === 'string' ? req.body.password : '';
  const weak = pw.checkStrength(password);
  if (weak) return next(badRequest(weak, 'weak_password'));
  const exists = await one('SELECT 1 FROM admins WHERE username=$1', [username]);
  if (exists) return next(badRequest('این نام کاربری گرفته شده است'));
  const row = await one(
    `INSERT INTO admins (id, username, name, password_hash, role, status, created_at)
     VALUES ($1,$2,$3,$4,$5,'active',$6) RETURNING id, username, name, role`,
    [newId('adm'), username, v.text(req.body?.name, { max: 60 }), await pw.hashPassword(password),
      v.oneOf(req.body?.role, ['admin', 'superadmin'], { field: 'نقش', def: 'admin' }), now()]
  );
  await audit.log({ actorType: 'admin', userId: req.admin.id, action: 'admin.admin_created', targetType: 'admin', targetId: row.id, detail: { username, role: row.role } });
  res.status(201).json({ admin: row });
});

router.get('/admins', requireSuperAdmin, async (req, res) => {
  res.json({ admins: await many('SELECT id, username, name, role, status, created_at FROM admins ORDER BY created_at') });
});

/**
 *  غیرفعال کردن یا عوض کردنِ نقشِ یک مدیر — فقط مدیرِ ارشد.
 *  ⚠️ نه خودش (قفل شدنِ ناخواسته) و نه آخرین مدیرِ ارشدِ فعال (پنلِ بی‌صاحب).
 *  غیرفعال ⇒ همهٔ نشست‌هایش همان دم بسته می‌شود.
 */
router.patch('/admins/:id', requireSuperAdmin, async (req, res, next) => {
  const id = String(req.params.id);
  if (id === req.admin.id) return next(badRequest('نقش یا وضعیتِ خودتان را نمی‌توانید عوض کنید', 'admin_self'));
  const target = await one('SELECT id, role, status FROM admins WHERE id=$1', [id]);
  if (!target) return next(notFound('مدیر پیدا نشد'));
  const status = req.body?.status === undefined ? target.status : v.oneOf(req.body.status, ['active', 'disabled'], { field: 'وضعیت' });
  const role = req.body?.role === undefined ? target.role : v.oneOf(req.body.role, ['admin', 'superadmin'], { field: 'نقش' });
  const losesSuper = target.role === 'superadmin' && target.status === 'active' && (role !== 'superadmin' || status !== 'active');
  if (losesSuper) {
    const left = await one(`SELECT COUNT(*)::int AS n FROM admins WHERE role='superadmin' AND status='active' AND id<>$1`, [id]);
    if (!left || left.n < 1) return next(badRequest('آخرین مدیرِ ارشدِ فعال نمی‌تواند کنار برود', 'last_superadmin'));
  }
  const row = await one('UPDATE admins SET status=$2, role=$3 WHERE id=$1 RETURNING id, username, name, role, status', [id, status, role]);
  if (status === 'disabled') await tokens.revokeAllForSubject(id);
  await audit.log({ actorType: 'admin', userId: req.admin.id, action: 'admin.admin_updated', targetType: 'admin', targetId: id, detail: { status, role } });
  res.json({ admin: row });
});

// ---------- پشتیبان‌گیری ----------
router.get('/backups', async (req, res) => {
  const backup = require('../lib/backup');
  //  F0-08: بی رمز ⇒ پنل هشدارِ قرمز می‌دهد (خودِ رمز هرگز این‌جا نمی‌آید)
  const configured = !!config.backup.passphrase;
  res.json({
    backups: await backup.list(), dir: config.backup.dir, enabled: config.backup.enabled,
    encryption: { configured, warning: configured ? '' : backup.UNENCRYPTED_WARNING },
  });
});

router.post('/backups', requireSuperAdmin, async (req, res, next) => {
  const backup = require('../lib/backup');
  const out = await backup.run({ kind: v.oneOf(req.body?.kind, ['daily', 'weekly', 'monthly', 'manual'], { field: 'نوع', def: 'manual' }) });
  await audit.log({ actorType: 'admin', userId: req.admin.id, action: 'admin.backup_created', detail: { file: out.file } });
  res.status(201).json(out);
});

/* ==========================================================
   بخش‌های تازه — تخفیف، کد وی‌آی‌پی، بازدیدکننده‌ها، پشتیبانی،
   اشتراک‌های رو به پایان، برنامه‌های دیگر، ایمیل و پوش.
   ----------------------------------------------------------
   در فایل جدا نوشته شده‌اند تا این فایل خوانا بماند، ولی زیر همان
   `requireAdmin` بالا سوارند — پس قاعده‌ی دسترسی همان یکی است.
   ========================================================== */
router.use('/logins', require('./admin-logins'));
//  میزِ «فروشگاه» — بندهای ۴.۲ و ۴.۳ سندِ ریمیک. فقط می‌خواند.
router.use('/shop-desk', require('./admin-shop-desk'));
router.use('/shop-offline-codes', require('./admin-shop-offline'));
//  میزِ «کدِ شاگرد» — بندِ ۴.۴ سندِ ریمیک. ⛔ زیرِ `/shops/:id` می‌نشیند تا
//  همان `v.id` و همان مرزِ دکان را داشته باشد، نه یک درِ موازی.
router.use('/shops/:id/staff-codes', require('./admin-staff-codes'));
//  مجوزهای کارمندان و دستگاه‌های یک دکان (STF-01..03، STF-10)
router.use('/shops/:id/staff-perms', require('./admin-staff-perms'));
/*
 *  ⚠️ **دو دفترِ کد هست و هر دو میز می‌خواهند.** `/logins` مالِ
 *  `login_requests` است (ورود با کدِ ایمیلی) و `/otp` مالِ `otp_codes`
 *  (ثبت‌نام، رمزِ فراموش‌شده، کدِ ورودِ ساده). دومی تا ۲.۸.۳ هیچ میزی
 *  نداشت و کدِ ثبت‌نامِ کاربرِ تازه هیچ‌جا دیده نمی‌شد.
 *
 *  ⛔ **این دو یکی نمی‌شوند**: دو جدول با دو قرارداد و دو عمرِ متفاوت.
 *  کارِ یکی کردنشان دستِ پنل است، که هر دو را می‌خواند و یک فهرست نشان
 *  می‌دهد.
 */
router.use('/otp', require('./admin-otp'));
router.use('/sync', require('./admin-sync'));
//  سلامتِ سرور (§۳۸.۸، OPS-01@38) — فقط عدد و وضعیت، بی هیچ راز
router.use('/system', require('./admin-system'));
router.use('/', require('./admin-platform'));
//  بخشِ پمپ‌بنزین — زیر همان `requireAdmin`، ولی روی دفترِ خودش
router.use('/pump', require('./admin-pump'));

module.exports = router;

changes.before:
'use strict';
/**
 * صفحهٔ کنترلِ مدیر — ضمانت‌های سمتِ سرورِ `docs/ADMIN-CONTROL-PLANE.md`
 * (بندِ ۳۹.۸ و ۲۹.۴ِ سند).
 *
 *   • توکنِ مدیر توکنِ دکان نیست — مدیر از درِ کاربر به دادهٔ دکان نمی‌رسد
 *   • «خروجیِ» دادهٔ خصوصیِ یک حساب (دانلودِ پشتیبانش) و «بازگرداندنِ»
 *     تعارضِ همگام‌سازی: فقط مدیرِ ارشد، با دلیلِ نوشته، با ردیفِ سابقه
 *   • برداشتنِ افزونهٔ پولی: فقط مدیرِ ارشد (مثلِ افزودنش) و فقط از همان
 *     اشتراکی که در نشانی آمده
 *   • کارهای مدیر که ردیفِ سابقه نداشتند: ردِ درخواستِ خرید، شهرِ کاربر،
 *     وضعیتِ گفت‌وگوی پشتیبانی
 *   • دیدنِ پروندهٔ کاربر (لوکیشنِ دقیق، دستگاه‌ها) و پروندهٔ دکان سابقه دارد
 */
const test = require('node:test');
const assert = require('node:assert/strict');
const h = require('./helpers');
const { query, many, newId, now } = require('../src/db');

test.before(async () => {
  await h.start();
  const pw = require('../src/lib/password');
  const hash = await pw.hashPassword('<redacted>');
  await query(
    `INSERT INTO admins (id, username, name, password_hash, role, status, created_at)
     VALUES ($1,'arshad','ارشد',$2,'superadmin','active',$3), ($4,'poshtiban','پشتیبان',$2,'admin','active',$3)`,
    [newId('adm'), hash, now(), newId('adm')]
  );
});
test.after(async () => { await h.stop(); });

const login = async (username) =>
  (await h.post('/api/admin/login', { username, password: '<redacted>' })).body.token;
const superToken = () => login('arshad');
const plainToken = () => login('poshtiban');

async function shopOwner(name) {
  const u = await h.newUser(name, 'shop');
  const made = await h.post('/api/shop', { name: `دکانِ ${name}` }, { token: u.accessToken });
  assert.equal(made.status, 201, JSON.stringify(made.body));
  return { ...u, shopId: made.body.shop.id };
}

const auditRows = (action, targetId) => many(
  `SELECT * FROM audit_logs WHERE action=$1 AND ($2 = '' OR target_id=$2) ORDER BY created_at`,
  [action, String(targetId || '')]
);
const detailOf = (row) => (typeof row.detail === 'string' ? JSON.parse(row.detail) : row.detail);

/* ── ۱) جداییِ tenant حتی برای مدیر ───────────────────────────────── */

test('توکنِ مدیر توکنِ دکان نیست: مسیرهای دادهٔ کاربر ۴۰۱ می‌دهند', async () => {
  const t = await superToken();
  for (const path of ['/api/me', '/api/me/backups']) {
    const r = await h.get(path, { token: t });
    assert.equal(r.status, 401, `${path} ⇒ ${r.status}`);
  }
});

/* ── ۲) خروجیِ دادهٔ خصوصی: دانلودِ پشتیبانِ یک حساب ─────────────── */

test('دانلودِ پشتیبانِ حساب: فقط ارشد، فقط با دلیل، با ردیفِ سابقه', async () => {
  const o = await shopOwner('صاحبِ پشتیبان');
  const data = Buffer.from('دفترِ خصوصیِ دکان');
  const up = await h.raw('POST', '/api/me/backups?ext=json', data, { token: o.accessToken });
  assert.equal(up.status, 201, JSON.stringify(up.body));
  const path = `/api/admin/accounts/shop/${o.shopId}/backups/${up.body.backup.id}`;

  const weak = await h.download(`${path}?reason=${encodeURIComponent('درخواستِ مشتری')}`, { token: await plainToken() });
  assert.equal(weak.status, 403, '⛔ مدیرِ عادی (پشتیبانی) خروجیِ دادهٔ کامل نمی‌گیرد');

  const t = await superToken();
  const noReason = await h.get(path, { token: t });
  assert.equal(noReason.status, 400);
  assert.equal(noReason.body.error.code, 'reason_required');
  assert.equal((await auditRows('admin.account_backup_downloaded', up.body.backup.id)).length, 0);

  const ok = await h.download(`${path}?reason=${encodeURIComponent('بازیابی به درخواستِ صاحب دکان')}`, { token: t });
  assert.equal(ok.status, 200);
  assert.ok(ok.buffer.equals(data));

  const rows = await auditRows('admin.account_backup_downloaded', up.body.backup.id);
  assert.equal(rows.length, 1);
  assert.equal(rows[0].actor_type, 'admin');
  assert.equal(rows[0].shop_id, o.shopId, 'ردیف به همان tenant بسته است');
  const d = detailOf(rows[0]);
  assert.equal(d.reason, 'بازیابی به درخواستِ صاحب دکان');
  assert.equal(d.app, 'shop');
  assert.equal(d.tenantId, o.shopId);
});

/* ── ۳) بازگرداندنِ تعارض (restore) ──────────────────────────────── */

test('بازگرداندنِ تعارضِ همگام‌سازی: فقط ارشد، فقط با دلیل', async () => {
  const weak = await h.post('/api/admin/sync/conflicts/1/restore', { reason: 'آزمون' }, { token: await plainToken() });
  assert.equal(weak.status, 403);

  const t = await superToken();
  const noReason = await h.post('/api/admin/sync/conflicts/1/restore', {}, { token: t });
  assert.equal(noReason.status, 400);
  assert.equal(noReason.body.error.code, 'reason_required');

  //  با دلیل از نگهبان می‌گذرد و به خودِ تعارض می‌رسد (که این‌جا نیست)
  const missing = await h.post('/api/admin/sync/conflicts/999999/restore', { reason: 'پیامِ صاحب دکان' }, { token: t });
  assert.equal(missing.status, 404);
});

test('دیدنِ تعارض‌های یک حساب (مقدارهای خصوصی) سابقه دارد', async () => {
  const o = await shopOwner('تعارض‌دار');
  const t = await superToken();
  const r = await h.get(`/api/admin/sync/conflicts?app=shop&account=${o.shopId}`, { token: t });
  assert.equal(r.status, 200);
  const rows = await auditRows('admin.sync_conflicts_viewed', o.shopId);
  assert.equal(rows.length, 1);
  assert.equal(rows[0].shop_id, o.shopId);
});

/* ── ۴) افزونهٔ پولی ───────────────────────────────────────────── */

test('برداشتنِ افزونه: فقط ارشد و فقط از همان اشتراک', async () => {
  const t = await superToken();
  const a = await shopOwner('افزونهٔ الف');
  const b = await shopOwner('افزونهٔ ب');
  const subA = (await h.post('/api/admin/subscriptions', { shopId: a.shopId, plan: 'm1', days: 30, features: ['sales'] }, { token: t })).body.subscription.id;
  const subB = (await h.post('/api/admin/subscriptions', { shopId: b.shopId, plan: 'm1', days: 30, features: ['sales'] }, { token: t })).body.subscription.id;
  const add = await h.post(`/api/admin/subscriptions/${subA}/addons`, { feature: 'barcode', price: 500 }, { token: t });
  assert.equal(add.status, 201, JSON.stringify(add.body));
  const addonId = add.body.addon.id;

  const weak = await h.del(`/api/admin/subscriptions/${subA}/addons/${addonId}`, { token: await plainToken() });
  assert.equal(weak.status, 403, '⛔ برداشتنِ قابلیتِ پولی مثلِ افزودنش کارِ ارشد است');

  const cross = await h.del(`/api/admin/subscriptions/${subB}/addons/${addonId}`, { token: t });
  assert.equal(cross.status, 404, '⛔ افزونهٔ اشتراکِ الف از نشانیِ اشتراکِ ب برداشته نمی‌شود');
  const still = await h.get(`/api/admin/subscriptions/${subA}/addons`, { token: t });
  assert.equal(still.body.addons.length, 1);
  assert.equal((await auditRows('admin.addon_removed', subB)).length, 0, 'ردیفِ سابقهٔ دروغ ساخته نمی‌شود');

  const gone = await h.del(`/api/admin/subscriptions/${subA}/addons/${addonId}`, { token: t });
  assert.equal(gone.status, 200);
  assert.equal((await auditRows('admin.addon_removed', subA)).length, 1);
});

/* ── ۵) کارهایی که ردیفِ سابقه نداشتند ───────────────────────────── */

test('ردِ درخواستِ خرید ردیفِ سابقه با دلیل دارد — و دوباره‌زدن ردیفِ دوم نمی‌سازد', async () => {
  const o = await shopOwner('خریدار');
  const made = await h.post('/api/me/purchase-request', { plan: 'm6' }, { token: o.accessToken });
  assert.equal(made.status, 201, JSON.stringify(made.body));
  const id = made.body.request.id;
  const t = await plainToken();

  const r = await h.post(`/api/admin/purchase-requests/${id}/reject`, { reason: 'رسیدِ پرداخت نرسید' }, { token: t });
